"""Fulfilment endpoints."""

from __future__ import annotations

from typing import Any

from orders.application.catalog_service import CatalogService
from orders.application.errors import Conflict, OrderNotFound, ProductNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, conflict, not_found, require_non_negative_int, require_positive_int, require_str


class FulfilmentController:
    def __init__(self, order_service: OrderService, catalog_service: CatalogService) -> None:
        self._order_service = order_service
        self._catalog_service = catalog_service

    def handle_packing_slip(self, order_id: str) -> Response:
        try:
            packing_slip = self._order_service.get_packing_slip(order_id)
        except OrderNotFound:
            return not_found("order")
        except Conflict as exc:
            return conflict(exc)
        return Response(200, packing_slip)

    def handle_low_stock(self, threshold: Any) -> Response:
        try:
            threshold_int = require_non_negative_int(threshold, "threshold")
        except InvalidRequest as exc:
            return bad_request(exc)
        low_stock = self._catalog_service.list_low_stock(threshold_int)
        products = [{"sku": p.sku, "name": p.name, "on_hand": stock} for p, stock in low_stock]
        return Response(200, {"products": products})

    def handle_restock(self, request: dict[str, Any]) -> Response:
        try:
            sku = require_str(request, "sku")
            quantity = require_positive_int(request.get("quantity"), "quantity")
        except InvalidRequest as exc:
            return bad_request(exc)
        try:
            new_stock = self._catalog_service.restock(sku, quantity)
        except ProductNotFound:
            return not_found("product")
        return Response(200, {"sku": sku, "on_hand": new_stock})

    def handle_fulfilment_summary(self) -> Response:
        open_orders = self._order_service.get_open_orders_count()
        units_to_pick = self._order_service.get_units_to_pick()
        low_stock_products = self._catalog_service.count_low_stock_products(5)
        return Response(200, {
            "open_orders": open_orders,
            "units_to_pick": units_to_pick,
            "low_stock_products": low_stock_products,
        })

def get_packing_slip(self, order_id: str) -> dict:
    order = self.get_order(order_id)
    if order.status == "cancelled":
        raise Conflict(f"order {order_id} is cancelled")
    customer = self._customers.get(order.customer_id)
    customer_name = customer.name if customer is not None else ""
    lines = []
    for item in order.items:
        product = self._catalog.get(item.sku)
        product_name = product.name if product is not None else item.sku
        lines.append({"sku": item.sku, "name": product_name, "quantity": item.quantity})
    return {"order_id": order.order_id, "customer_name": customer_name, "lines": lines}

def get_open_orders_count(self) -> int:
    return sum(1 for order in self._orders.list_all() if order.status != "cancelled")

def get_units_to_pick(self) -> int:
    total = 0
    for order in self._orders.list_all():
        if order.status != "cancelled":
            total += sum(item.quantity for item in order.items)
    return total

def restock(self, sku: str, quantity: int) -> int:
    self.get_product(sku)
    current_stock = self._stock.get(sku)
    new_stock = current_stock + quantity
    self._stock.set(sku, new_stock)
    return new_stock

def count_low_stock_products(self, threshold: int) -> int:
    return sum(1 for product in self.list_active() if self._stock.get(product.sku) < threshold)
